let _markdown = "\n\nUsage [#usage]\n\n<FeedbackBlock id=\"40cf74b5ad814dba\" body=\"Pass your repository name, and the path to file.\">\n  Pass your repository name, and the path to file.\n</FeedbackBlock>\n\n```ts\nimport { getGithubLastEdit } from 'fumadocs-core/content/github';\n\nconst time = await getGithubLastEdit({\n  owner: 'fuma-nama',\n  repo: 'fumadocs',\n  // example: \"content/docs/index.mdx\"\n  path: `content/docs/${page.path}`,\n});\n```\n\nGithub Token [#github-token]\n\n<FeedbackBlock\n  id=\"55b7f92139423164\"\n  body=\"Notice that you may easily reach the rate limit in development mode. Hence, you\nshould pass a Github token for a higher rate limit.\"\n>\n  Notice that you may easily reach the rate limit in development mode. Hence, you\n  should pass a Github token for a higher rate limit.\n</FeedbackBlock>\n\n<FeedbackBlock\n  id=\"88ed6d08d7ef8407\"\n  body=\"Learn more about\nAuthenticating to the REST API.\"\n>\n  Learn more about\n  [Authenticating to the REST API](https://docs.github.com/en/rest/overview/authenticating-to-the-rest-api).\n</FeedbackBlock>\n\n```ts\nimport { getGithubLastEdit } from 'fumadocs-core/content/github'\n\n const time = await getGithubLastEdit({\n    ...,\n    token: `Bearer ${process.env.GIT_TOKEN}`\n  })\n```\n\n<FeedbackBlock\n  id=\"b240e98be746ef1a\"\n  body=\"Also, you can skip this in development mode if you don't need that\nfunctionality.\"\n>\n  Also, you can skip this in development mode if you don't need that\n  functionality.\n</FeedbackBlock>\n\n```ts\nprocess.env.NODE_ENV === 'development'? null : getGithubLastEdit(...)\n```\n\nCustom GitHub Base URL [#custom-github-base-url]\n\n<FeedbackBlock id=\"a5716e1941f36782\" body=\"If you need to access GitHub a instance at a url other than https://api.github.com, you can override the base URL:\">\n  If you need to access GitHub a instance at a url other than `https://api.github.com`, you can override the base URL:\n</FeedbackBlock>\n\n```ts\nimport { getGithubLastEdit } from 'fumadocs-core/content/github';\n\nconst time = await getGithubLastEdit({\n  owner: 'your-org',\n  repo: 'your-repo',\n  path: `content/docs/${page.path}`,\n  baseUrl: 'https://api.octocorp.ghe.com', // Your custom GitHub API URL\n});\n```\n\n<FeedbackBlock id=\"82bda8fbd5bd9525\" body=\"The baseUrl parameter defaults to 'https://api.github.com' if not specified.\">\n  The `baseUrl` parameter defaults to `'https://api.github.com'` if not specified.\n</FeedbackBlock>\n";
